-- Code generated by togo. PostgreSQL query fragment - safe to edit.

-- Hosbah queries (MH-580 J6: SSL expiry).

-- name: ListTeamCertificates :many
-- Any member: the team's certificates, worst (soonest expiry, then failing) first.
SELECT * FROM ssl_certificates WHERE team_id = sqlc.arg('team_id')
  ORDER BY (not_after IS NULL) DESC, not_after ASC, hostname ASC;

-- name: SystemHostnamesForSSL :many
-- System scope (the checker): every hostname across every team whose tls is 'auto' — an app domain
-- or a proxy host, each carrying a public certificate worth watching.
SELECT team_id, hostname, 'app'::text AS source FROM domains WHERE tls = 'auto'
UNION ALL
SELECT team_id, hostname, 'proxy'::text AS source FROM proxy_hosts WHERE tls = 'auto';

-- name: UpsertSSLCertificate :one
-- System scope (Scope{System: true, TeamID: ...}), the checker: one hostname's reading. Alerted
-- flags are only ever cleared here (a renewal or a recovered check resets them); SetSSLAlerted sets
-- them once a threshold has fired.
INSERT INTO ssl_certificates (team_id, hostname, source, ok, issuer, not_before, not_after, san_match, error, last_checked_at,
    alerted_14, alerted_7, alerted_1, alerted_failure)
VALUES (sqlc.arg('team_id'), sqlc.arg('hostname'), sqlc.arg('source'), sqlc.arg('ok'), sqlc.arg('issuer'),
    sqlc.narg('not_before'), sqlc.narg('not_after'), sqlc.arg('san_match'), sqlc.arg('error'), sqlc.arg('last_checked_at'),
    false, false, false, false)
ON CONFLICT (team_id, hostname) DO UPDATE SET
    source = excluded.source, ok = excluded.ok, issuer = excluded.issuer, not_before = excluded.not_before,
    not_after = excluded.not_after, san_match = excluded.san_match, error = excluded.error, last_checked_at = excluded.last_checked_at,
    alerted_14 = CASE WHEN excluded.ok AND ssl_certificates.not_after IS NOT DISTINCT FROM excluded.not_after THEN ssl_certificates.alerted_14 ELSE false END,
    alerted_7 = CASE WHEN excluded.ok AND ssl_certificates.not_after IS NOT DISTINCT FROM excluded.not_after THEN ssl_certificates.alerted_7 ELSE false END,
    alerted_1 = CASE WHEN excluded.ok AND ssl_certificates.not_after IS NOT DISTINCT FROM excluded.not_after THEN ssl_certificates.alerted_1 ELSE false END,
    alerted_failure = CASE WHEN excluded.ok THEN false ELSE ssl_certificates.alerted_failure END,
    updated_at = now()
RETURNING *;

-- name: SetSSLAlerted :exec
-- System scope: mark one dedup flag ('alerted_14' | 'alerted_7' | 'alerted_1' | 'alerted_failure') set, after the notification went out.
UPDATE ssl_certificates SET
    alerted_14 = CASE WHEN sqlc.arg('flag')::text = 'alerted_14' THEN true ELSE alerted_14 END,
    alerted_7 = CASE WHEN sqlc.arg('flag')::text = 'alerted_7' THEN true ELSE alerted_7 END,
    alerted_1 = CASE WHEN sqlc.arg('flag')::text = 'alerted_1' THEN true ELSE alerted_1 END,
    alerted_failure = CASE WHEN sqlc.arg('flag')::text = 'alerted_failure' THEN true ELSE alerted_failure END,
    updated_at = now()
WHERE id = sqlc.arg('id');
